    # Access fragment type (mixed in!)
    print(source_key.fragment.type)  # FragmentType.AUTHOR_ID

    # Serialize
    key_str = source_key.to_string_key()  # "authors.parquet#author_id:A12345"

    # Deserialize
    restored = SourceKey.from_string_key(key_str, resource)
