@implements[BackendComponent.ContextProperty]()
class AiAugmentBackendContext(BaseModel):
    model_config = ConfigDict(
        arbitrary_types_allowed=True,
        extra="forbid",
        frozen=True,
        strict=True,
    )

    pipeline_config: AiAugmentDetourConfig
    configured_namekey: NameKey | None = None
    cached_ai_augment_outerdicts: tuple[AiAugmentOuterDict, ...] | None = Field(
        default=None,
        exclude=True,
        repr=False,
    )

    def ai_augment_outerdicts_factory(self) -> tuple[AiAugmentOuterDict, ...]:
        if self.cached_ai_augment_outerdicts is not None:
            return self.cached_ai_augment_outerdicts
        release_map = self.pipeline_config.resources.release_map
        release_batches = _load_release_batches(Path(release_map))
        source_conn: duckdb.DuckDBPyConnection | None = None
        try:
            source_conn = duckdb.connect(
                str(self.pipeline_config.db_file),
                read_only=True,
            )
            return _derive_ai_augment_outerdicts(
                source_conn,
                release_batches,
                sample_seed=self.pipeline_config.sample_seed,
            )
        except duckdb.Error as exc:
            raise ValueError(Locale.SOURCE_DUCKDB_VALIDATION_FAILED) from exc
        finally:
            if source_conn is not None:
                source_conn.close()

    @computed_field(repr=False)  # type: ignore[prop-decorator]
    @cached_property
    def ai_augment_outerdicts(self) -> tuple[AiAugmentOuterDict, ...]:
        return self.ai_augment_outerdicts_factory()

    def configured_ai_augment_outerdict(
        self,
    ) -> AiAugmentOuterDict | None:
        if self.configured_namekey is None:
            return None
        matches = tuple(
            outerdict
            for outerdict in self.ai_augment_outerdicts
            if outerdict.namekey == self.configured_namekey
        )
        if len(matches) != 1:
            raise ValueError("configured AI augment outerdict is missing or duplicated")
        return matches[0]
        commit_ids = tuple(
            committed.commit_record.record_id
            for committed in self.committed_innerdicts
        )
        if len(set(commit_ids)) != len(commit_ids):
            raise ValueError("AI augment committed innerdict IDs are duplicated")
        if commit_ids != tuple(sorted(commit_ids, key=lambda value: value.int)):
            raise ValueError("AI augment committed innerdicts are not ordered")
        for committed in self.committed_innerdicts:
            committed_namekey = name_key_from_header_value(
                committed.commit_record.request_headers.get(NAME_KEY_HEADER)
            )
            if committed_namekey != self.namekey:
                raise ValueError("AI augment committed innerdict has another namekey")
        return self

    def ground_truth_innerdict(self) -> InnerDict | None:
        if self.ai_augment_cohort is AiAugmentCohort.NO_GROUND_TRUTH:
            return None
        required_columns = tuple(
            column
            for column in DOCX_COLUMNS
            if column not in KTP_DOCX_OPTIONAL_EMPTY_COLS
        )
        complete_rows = tuple(
            innerdict
            for innerdict in self.docx_innerdicts
            if all(
                column in innerdict.data
                and bool(str(innerdict.data[column]).strip())
                for column in required_columns
            )
        )
        if not complete_rows:
            raise ValueError(Locale.GROUND_TRUTH_DOCX_INCOMPLETE)
        return complete_rows[0]

    @model_validator(mode="after")
    def _validate_ai_augment_outerdict(self) -> Self:
        return self.validate_ai_augment_outerdict()

    @classmethod
    def from_serialized(cls, value: Mapping[str, object]) -> Self:
        serialized = _AiAugmentOuterDictJson.model_validate_json(json.dumps(value))
        return cls(
            namekey=serialized.namekey,
            xlsx_innerdicts=tuple(
                InnerDict.from_mapping(innerdict, XlsxMatchProcedure())
                for innerdict in serialized.xlsx_innerdicts
            ),
            ssn_innerdicts=tuple(
                InnerDict.from_mapping(innerdict, ParquetMatchProcedure())
                for innerdict in serialized.ssn_innerdicts
            ),
            docx_innerdicts=tuple(
                InnerDict.from_mapping(innerdict, DocxMatchProcedure())
                for innerdict in serialized.docx_innerdicts
            ),
            committed_innerdicts=tuple(
                CommittedInnerDict.from_serialized(innerdict.model_dump(mode="json"))
                for innerdict in serialized.committed_innerdicts
            ),
            ai_augment_rnd=serialized.ai_augment_rnd,
            ai_augment_cohort=serialized.ai_augment_cohort,
            ai_augment_ineligibility_category=(
                serialized.ai_augment_ineligibility_category
            ),
        )

    def serialize(self) -> dict[str, object]:
        return _AiAugmentOuterDictJson.from_ai_augment_outerdict(self).model_dump(
            mode="json"
        )

    @model_serializer
    def _serialize(self) -> dict[str, object]:
        return self.serialize()

