        f"FROM {AUTHORITATIVE_RECORDS_TABLE} "
        f"WHERE {AUTHORITATIVE_RECORD_ID_COLUMN} = ?",
        [str(record_id)],
    ).fetchone()
    if row is None:
        raise _PushValidationError(Locale.REPLAY_COMMIT_LINK_MISSING)
