def _http_header_value(
    headers: Mapping[str, object] | None,
    name: str,
) -> str | None:
    if headers is None:
        return None
    normalized_name = name.casefold()
    for key, value in headers.items():
        if key.casefold() == normalized_name and isinstance(value, str):
            return value
    return None


